// Generated by `next typegen` (and by `next build` and `next dev`): every
// page of the app and the params each one takes. `check-types` and `lint`
// run typegen first. `next-route-types/*` (tsconfig `paths`) tries each build
// folder in turn, because the e2e build writes to `.next-e2e` and
// `next dev` to `.next/dev`.
import type { AppRoutes, ParamMap } from "next-route-types/routes";

/**
 * A page with a dynamic segment, written the way its folder is named:
 * `/app/projects/[id]/teams`.
 */
export type DynamicPage = {
  [P in AppRoutes]: keyof ParamMap[P] extends never ? never : P;
}[AppRoutes];

/** A page without one: `/app/settings`. */
export type StaticPage = Exclude<AppRoutes, DynamicPage>;

/** What may follow the path: nothing, a query string or a fragment. */
export type HrefSuffix = "" | `?${string}` | `#${string}`;

/** `/app/projects/[id]/teams` → `` `/app/projects/${string}/teams` ``. */
type Filled<P extends string> =
  P extends `${infer Head}[${string}]${infer Tail}`
    ? `${Head}${string}${Filled<Tail>}`
    : P;

/**
 * The address of any page of the app (ADR CM-0045): a static page as a
 * literal (`"/app/settings"`, `"/app/settings?tab=company"`), or what
 * `pageHref` returns. Use it for every prop or field that holds a link.
 */
export type AppHref = `${StaticPage | Filled<DynamicPage>}${HrefSuffix}`;

/**
 * The address of a page with a dynamic segment (ADR CM-0045).
 *
 * Next's typed routes check a literal such as `"/app/settings"`, but a
 * template such as `` `/app/projects/${id}/resources` `` still passes after
 * the page moved, because a dynamic segment matches any text, slashes
 * included. Naming the page by its folder instead makes a moved or renamed
 * page fail `check-types` wherever it is linked:
 *
 * ```ts
 * pageHref("/app/projects/[id]/teams", { id: projectId });
 * pageHref("/app/projects/[id]/worksheets/[sheetId]", { id, sheetId }, "?uploaded=1");
 * ```
 *
 * Each param is URL-encoded.
 */
export function pageHref<P extends DynamicPage, S extends HrefSuffix = "">(
  page: P,
  params: ParamMap[P],
  suffix?: S,
): `${Filled<P>}${S}` {
  const values = params as Record<string, string | undefined>;
  const path = page.replace(/\[([^\]]+)\]/g, (_segment, name: string) =>
    encodeURIComponent(values[name] ?? ""),
  );
  return `${path}${suffix ?? ""}` as `${Filled<P>}${S}`;
}

/**
 * A page address the code did not build, so nothing can check it: the
 * current URL (`usePathname()` plus a new query), a return path that
 * `safeAppPath` accepted, or a link stored with a Notification. Never use it
 * for an address the code puts together; use `pageHref` or a literal.
 */
export function uncheckedHref(path: string): AppHref {
  return path as AppHref;
}
